{"hypotheses": [
  {
    "name": "H1",
    "mechanism": "High financial leverage and high systematic volatility (betaVIX) companies tend to underperform, especially during market down periods. The added marketing spending (AdExp) might be an attempt to boost sales and could indicate distress.",
    "expression": {
      "terms": [
        {"weight": -0.5, "primitive": "Leverage"},
        {"weight": -0.5, "primitive": "betaVIX"},
        {"weight": 1.0, "primitive": "AdExp"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "Leverage", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "H2",
    "mechanism": "Companies with high institutional ownership (IO_ShortInterest) and high short interest tend to underperform. This is especially true in volatile markets, as institutions may be forced to liquidate holdings due to redemption pressures.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "IO_ShortInterest"},
        {"weight": -1.0, "primitive": "ShortInterest"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "H3",
    "mechanism": "Companies with high analyst optimism (AOP) and high short term reversal (STreversal) tend to underperform due to overoptimism and eventual price correction.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AOP"},
        {"weight": -1.0, "primitive": "STreversal"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "AOP", "bound": "above", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 60
  },
  {
    "name": "H4",
    "mechanism": "Companies with high dividends (DivYieldST) and low short term reversal (STreversal) tend to outperform due to the fact that they are less likely to cut dividends and their prices revert less.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "DivYieldST"},
        {"weight": 0.5, "primitive": "STreversal"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "DivYieldST", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "H5",
    "mechanism": "Companies with high asset growth (AssetGrowth) and low volatility of turnover (std_turn) tend to outperform due to anticipated consistent growth and stable customer base.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": 0.5, "primitive": "std_turn"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "H6",
    "mechanism": "Companies with high R&D spending (RD) and high analyst optimism (AOP) tend to outperform due to anticipated innovation and positive market sentiment.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": 0.5, "primitive": "AOP"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "RD", "bound": "above", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 1.0,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "H7",
    "mechanism": "Companies with high institutional ownership (IO_ShortInterest) and high broker recommendations (ConsRecomm) tend to outperform due to superior information and market confidence.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IO_ShortInterest"},
        {"weight": 1.0, "primitive": "ConsRecomm"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "IO_ShortInterest", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "H8",
    "mechanism": "Companies with low intangible returns using EP (IntanEP) and high R&D ability (RDAbility) tend to underperform due to overinvestment in intangibles and misaligned R&D strategy.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "IntanEP"},
        {"weight": 1.0, "primitive": "RDAbility"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "lower"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "RDAbility", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.5,
    "expected_decay_half_life_months": 60
  }
]}
